/** Id do MAPA DO MUNDO no hexmap-store — o mapa-múndi é superfície do app
 *  (#419/#420), não um doc da vault. */
export const MAPA_MUNDO_ID = 'mapa:mundo'

// #420: o mapa-múndi (atlas.webp 7440×5262) é a MESMA grade do mundo
// re-renderizada em s=0.74777 — calibrado por âncoras (pin do mestre no
// Krasnogor + emblemas de Canto Alto/Baar'Shava/Safira; residuais ≤5px) e
// autocorrelação da malha desenhada (HSTEP 83px, VSTEP 96px = 0.748× a grade
// do Mundo Livre), conferido visualmente nos 4 cantos. O seed do mundo é
// DERIVADO do Mundo Livre pelo rebase (col+44, row+5 — atlas-grid.ts);
// nunca editar células na mão.
SEED_HEXMAPS[MAPA_MUNDO_ID] = (
  SEED_HEXMAPS['Atlas/Mundo Livre/Mundo Livre'] as Array<Record<string, unknown>>
).map((c) => ({ ...c, col: (c.col as number) + 44, row: (c.row as number) + 5 }))
